@@ -461,13 +461,8 @@ export const TargetBoardMatrix: React.FC<TargetBoardMatrixProps> = ({
   const handleDragEnd = (event: DragEndEvent) => {
     const { active, over } = event;
     if (over && active.id !== over.id) {
-      // Create a sorted version of the entire target board to act as the source of truth
-      const masterList = [...targetRecruits].sort((a, b) => {
-        if (a.boardOrder !== undefined && b.boardOrder !== undefined) return a.boardOrder - b.boardOrder;
-        if (a.boardOrder !== undefined) return -1;
-        if (b.boardOrder !== undefined) return 1;
-        return (b.starRating || 0) - (a.starRating || 0);
-      });
+      // ⚡ Bolt: Reuse the already memoized and sorted target board to act as the source of truth
+      const masterList = sortedTargetRecruits;

       const masterOldIndex = masterList.findIndex(r => r.id === active.id);
       const masterNewIndex = masterList.findIndex(r => r.id === over.id);

